<script>document.addEventListener('DOMContentLoaded',()=>{const tabs=[...document.querySelectorAll('.p-tabs a')];tabs.forEach(a=>a.onclick=e=>{const t=document.querySelector(a.getAttribute('href'));if(t){e.preventDefault();t.scrollIntoView({behavior:'smooth'});tabs.forEach(x=>x.parentElement.classList.remove('active'));a.parentElement.classList.add('active')}});const s=document.querySelector('.p-sort'),l=document.querySelector('.p-review-list');if(s&&l)[...s.children].forEach((b,i)=>b.onclick=()=>{[...s.children].forEach(x=>x.classList.remove('active'));b.classList.add('active');[...l.children].sort((a,c)=>i?(+c.dataset.rating-+a.dataset.rating):(+c.dataset.date-+a.dataset.date)).forEach(x=>l.appendChild(x))});const q=document.querySelector('.p-question-sort'),ql=document.querySelector('.p-question-list');if(q&&ql)[...q.children].forEach((b,i)=>b.onclick=()=>{[...q.children].forEach(x=>x.classList.remove('active'));b.classList.add('active');[...ql.children].sort((a,c)=>i?(+c.dataset.answers-+a.dataset.answers):(+c.dataset.date-+a.dataset.date)).forEach(x=>ql.appendChild(x))})});</script>
